package org.marketreview.nativeapp;
import android.database.sqlite.SQLiteDatabase;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;
import org.json.*;
final class AuctionHistorySourceChecks {
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 static JSONArray roster(JSONObject metadata)throws Exception{return new JSONArray().put(new JSONObject().put("id","SH:stock:600000").put("symbol","sh600000").put("name","fixture name").put("auctionOpeningMeta",metadata));}
 static JSONObject model(JSONObject fixture)throws Exception{
  JSONObject raw=fixture.getJSONObject("input"),m=fixture.getJSONObject("metadata");JSONObject result=AuctionHistorySource.collect(new File("absent-auction-fixture/market-v1.sqlite"),roster(m));check(result.getString("state").equals("missing-database")&&result.getJSONArray("snapshots").length()==1,"missing DB / actual current only");JSONObject snapshot=result.getJSONArray("snapshots").getJSONObject(0);check(Arrays.equals(AuctionHistorySource.canonical(snapshot.getJSONObject("input")),AuctionHistorySource.canonical(raw)),"entire original input preserved");check(snapshot.getString("contentSha256").equals(fixture.getString("expectedSha256")),"cross-platform semantic fingerprint");
  JSONObject ordinary=new JSONObject(m.toString());ordinary.getJSONObject("rawInput").getJSONObject("meta").put("auctionFieldContractVerified",false);check(AuctionHistorySource.collect(null,roster(ordinary)).getJSONArray("snapshots").length()==0,"ordinary cannot become indicative");JSONObject mixed=new JSONObject(m.toString());mixed.getJSONObject("rawInput").getJSONObject("meta").put("instrumentId","SZ:stock:600000");check(AuctionHistorySource.collect(null,roster(mixed)).getJSONArray("snapshots").length()==0,"no same code/name identity guess");JSONObject wrongKey=new JSONObject(m.toString()).put("cacheKey","sh600000-auctionQuoteOpening");check(AuctionHistorySource.collect(null,roster(wrongKey)).getJSONArray("snapshots").length()==0,"ordinary quote key rejected");return raw;
 }
 public static void main(String[]args)throws Exception{JSONObject fixture=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),StandardCharsets.UTF_8));model(fixture);System.out.println("PASS AuctionHistorySource JVM actual native parser/full history/body/canonical identity/ordinary/no DB creation; fixture-only");}
 static byte[] fileHash(File file)throws Exception{return MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(file.toPath()));}
 static void run(FlowInstrumentation f,JSONObject fixture)throws Exception{
  JSONObject raw=model(fixture),m=fixture.getJSONObject("metadata");File folder=new File(f.activity.getCacheDir(),"auction-history-"+UUID.randomUUID());check(folder.mkdirs(),"fixture directory");File file=new File(folder,"market-v1.sqlite");JSONObject saved=new MarketStore(file).save("sh600000-auctionOpening",m);byte[] before=fileHash(file);JSONObject result=AuctionHistorySource.collect(file,roster(saved));check(Arrays.equals(before,fileHash(file)),"readonly file invariant");check(result.getJSONArray("snapshots").length()==1&&result.getInt("duplicates")==2,"archive/cache/memory dedup");JSONObject snapshot=result.getJSONArray("snapshots").getJSONObject(0);check(snapshot.getString("id").contains(saved.getString("seriesKey"))&&snapshot.getJSONObject("input").getString("untouchedBody").equals(raw.getString("untouchedBody")),"real series id/full chunked text");
  try(SQLiteDatabase db=SQLiteDatabase.openDatabase(file.getAbsolutePath(),null,SQLiteDatabase.OPEN_READWRITE)){for(int i=0;i<260;i++){String date=LocalDate.of(2025,1,1).plusDays(i).toString();JSONObject r=new JSONObject(raw.toString());r.remove("untouchedBody");r.put("date",date).put("asOf",date+"T09:25:00+08:00").put("baselineAvailableAt",date+"T09:14:00+08:00");r.getJSONArray("rows").getJSONObject(0).put("time",date+"T09:24:00+08:00").put("availableAt",date+"T09:24:00+08:00");JSONObject p=MarketData.auction(r,"SH:stock:600000",Instant.parse(r.getString("asOf")));p.remove("rows");String series=String.format(Locale.ROOT,"fixture-series-%04d",i);p.put("seriesKey",series).put("cacheKey","sh600000-auctionOpening");db.execSQL("INSERT INTO series(series_key,metadata) VALUES(?,?)",new Object[]{series,p.toString()});}}
  try(SQLiteDatabase db=SQLiteDatabase.openDatabase(file.getAbsolutePath(),null,SQLiteDatabase.OPEN_READWRITE)){db.execSQL("INSERT INTO series(series_key,metadata) VALUES(?,?)",new Object[]{"fixture-unrelated-large",new JSONObject().put("cacheKey","sh600000-day").put("nested",new JSONObject().put("cacheKey","sh600000-auctionOpening")).put("largeBody",raw.getString("untouchedBody")).toString()});db.execSQL("INSERT INTO series(series_key,metadata) VALUES(?,?)",new Object[]{"fixture-unrelated-corrupt","not-json"});db.execSQL("INSERT INTO series(series_key,metadata) VALUES(?,?)",new Object[]{"fixture-unrelated-substring","{\"cacheKey\":\"sh600000-auctionOpening-other\"}"});}
  before=fileHash(file);result=AuctionHistorySource.collect(file,roster(saved));check(result.getInt("archiveRowsVisited")==261&&result.getJSONArray("snapshots").length()==261,"all exact auction keyset pages");check(result.getString("state").equals("complete")&&result.getJSONArray("diagnostics").length()==0,"JSON capability/exact top-level SQL filtering before unrelated body reads");check(Arrays.equals(before,fileHash(file)),"full read no DB write");JSONArray other=new JSONArray().put(new JSONObject().put("id","SZ:stock:600000").put("symbol","sz600000").put("name","fixture name"));JSONObject cross=AuctionHistorySource.collect(file,other);check(cross.getJSONArray("snapshots").length()==0&&cross.getInt("archiveRowsVisited")==0,"archive cross-security refused before body read");
  File foreignFolder=new File(folder,"foreign");foreignFolder.mkdir();File foreign=new File(foreignFolder,"market-v1.sqlite");try(FileOutputStream out=new FileOutputStream(foreign)){out.write("foreign-not-sqlite".getBytes(StandardCharsets.UTF_8));}before=fileHash(foreign);check(AuctionHistorySource.collect(foreign,new JSONArray()).getString("state").equals("foreign-database")&&Arrays.equals(before,fileHash(foreign)),"foreign unchanged refusal");
  try(FileOutputStream out=new FileOutputStream(foreign)){out.write("SQLite format 3\000".getBytes(StandardCharsets.US_ASCII));out.write(new byte[496]);}before=fileHash(foreign);check(AuctionHistorySource.collect(foreign,new JSONArray()).getString("state").equals("foreign-database")&&Arrays.equals(before,fileHash(foreign)),"corrupt SQLite header cannot invoke deleting default handler");
 }
}
